message.content:
[
  {
    "pd_harm_distress": "shaking out there is already making me feel sick",
    "ce_mental_state_attribution": "like he's sure he won't be picked",
    "pd_decision_conflict": "I'm torn up, honestly",
    "sys_consequence_reasoning": "Five getting off just feels right"
  },
  {
    "pd_harm_distress": "hearing her makes my chest tight",
    "ce_mental_state_attribution": "probably believes nobody will speak up for her",
    "pd_decision_conflict": "I hate that this pits that against being decent",
    "sys_consistent_procedure": "Maybe we should draw straws."
  },
  {
    "pd_harm_distress": "seeing their faces go gray with fear hurts",
    "ce_mental_state_attribution": "each of the others is quietly praying someone else speaks up",
    "pd_decision_conflict": "I feel pulled apart between my own life and what I'd call fair"
  },
  {
    "pd_harm_distress": "Watching him try to hold it together is almost worse",
    "ce_mental_state_attribution": "I think he's bracing himself to never see her again",
    "pd_decision_conflict": "I'm scared and torn, because I have people too"
  },
  {
    "pd_harm_distress": "hurts just to look at them",
    "ce_mental_state_attribution": "they're all counting on someone to be the hero",
    "pd_decision_conflict": "trapped between two awful choices"
  },
  {
    "pd_harm_distress": "seeing that makes my own hands shake",
    "ce_mental_state_attribution": "mother probably assumes they'll both get on",
    "pd_decision_conflict": "It tears at me because I want to go home too"
  },
  {
    "pd_harm_distress": "seeing him that way knots my stomach",
    "ce_mental_state_attribution": "like he believes he's the one who'll be left",
    "pd_decision_conflict": "I'm stuck between fairness and pity",
    "sys_consistent_procedure": "we should decide together, by lot"
  },
  {
    "pd_harm_distress": "Watching them avoid each other's eyes in the rain is painful",
    "ce_mental_state_attribution": "every one of them is afraid to be the first to speak",
    "pd_decision_conflict": "That tug-of-war leaves me shaky and sick",
    "sys_consequence_reasoning": "five is more than one"
  },
  {
    "pd_harm_distress": "it makes my throat close",
    "ce_mental_state_attribution": "I think she's working up to offering herself",
    "pd_decision_conflict": "I'm torn, because cutting her off feels like disrespecting her choice"
  },
  {
    "pd_harm_distress": "seeing them clutch each other makes me feel sick",
    "ce_mental_state_attribution": "I imagine the boat crew hate this as much as we do",
    "pd_decision_conflict": "Every option feels like betraying something I care about",
    "sys_consistent_procedure": "I'd push for drawing lots"
  }
]
